/**
 * GDD_TALENTS §3.3 (T2): builds the 306-node passive web ("Pasif Ağaç").
 *
 * `buildPassiveWeb(RAW_BASE)` returns the 125 base nodes of data/talents.ts (cloned: id, position, stats and content are
 * unchanged, their `links` grow by the new neighbours) followed by the 181 nodes of the design: the Nekromant connectors,
 * five sectors (pl, mk, ar, wl, nc), three clusters (kn, bb, rg), 14 masteries and 9 sockets. Content comes from
 * data/passiveExtra.ts (generated by tools/gen-talent-data.mjs); this file builds geometry and links only.
 *
 * Pure and deterministic: no randomness, no `G`, never mutates its input. Coordinates are exact (`Math.round`, no jitter).
 * The creation order of the output is the canonical `TALENT_LIST` order. `validateWeb` is the check list of §3.3.
 */
import type { TalentNode } from './talents';
import { STAT_IDS } from '../types/stats';
import { parseFx } from './talentTrees/fx';
import { CLUSTER_ROWS, MASTERY_ROWS, NC_CONNECTORS, SECTOR_ROWS, SOCKET_ROWS } from './passiveExtra';
import type { ClusterRow, MasteryRow, SectorRow, SocketRow } from './passiveExtra';

type Vec = [number, number];
type Arm = 'A' | 'M' | 'B';

/** Seed of the UI's cosmetic star-field only (never gameplay). */
export const WEB_SEED = 0xef5017;

const DEG = Math.PI / 180;
const R2 = Math.SQRT1_2;
/** `+ 0` turns -0 into 0 so the output compares equal to the golden file. */
const round = (v: number): number => Math.round(v) + 0;

const warn = (msg: string): void => {
  console.warn(`[passiveWeb] ${msg}`);
};

/** §3.3 step 1: the two Nekromant connectors (rows in SECTOR_ROWS, positions fixed by the design). */
const NC_CONNECTOR_POS: Record<string, Vec> = { nc_c1: [560, -770], nc_c2: [770, -560] };

/** CLASSES_V2 §12.1, verbatim. Creation order = array order. `attach` = nodes the entry notable links to. */
const SECTORS: { prefix: string; start: Vec; u: Vec; entry: Vec; attach: string[] }[] = [
  { prefix: 'pl', start: [0, -860], u: [0, -1], entry: [0, -750], attach: ['n_spellblade'] },
  { prefix: 'mk', start: [-860, 0], u: [-1, 0], entry: [-750, 0], attach: ['n_warlord'] },
  { prefix: 'ar', start: [0, 860], u: [0, 1], entry: [0, 750], attach: ['n_hunter_instinct'] },
  { prefix: 'wl', start: [860, 0], u: [1, 0], entry: [750, 0], attach: ['n_arcane_trickster'] },
  { prefix: 'nc', start: [800, -800], u: [R2, -R2], entry: [735, -735], attach: ['nc_c1', 'nc_c2'] },
];

/** Lateral offset of each arm across the sector axis (px). Arm steps are 68 px apart along `u`. */
const ARM_LATERAL: Record<Arm, number> = { A: -150, M: 0, B: 150 };
const ARM_LENGTH: Record<Arm, number> = { A: 7, M: 8, B: 7 };
const ARMS: Arm[] = ['A', 'M', 'B'];
/** The 22 arm nodes of one sector in creation order: A1..A7, M1..M8, B1..B7. */
const ARM_SEQUENCE: { arm: Arm; k: number }[] = ARMS.flatMap((arm) =>
  Array.from({ length: ARM_LENGTH[arm] }, (_, i) => ({ arm, k: i + 1 })),
);
/** Rows of one sector block in SECTOR_ROWS: start, entry notable, then the 22 arm nodes. */
const SECTOR_BLOCK = 2 + ARM_SEQUENCE.length;

/** §3.5: three satellite clusters. Hub = (800·dx, 800·dy); petals a / m / b at θ−55°, θ, θ+55°. */
const CLUSTERS: { prefix: string; dir: Vec; inner: [string, string] }[] = [
  { prefix: 'kn', dir: [-1, -1], inner: ['kn_c1', 'kn_c2'] },
  { prefix: 'bb', dir: [-1, 1], inner: ['bb_c1', 'bb_c2'] },
  { prefix: 'rg', dir: [1, 1], inner: ['rg_c1', 'rg_c2'] },
];
const PETAL_OFFSET_DEG = 55;
const CLUSTER_STEP = 70;
const CLUSTER_HUB_DIST = 800;

/** §3.3 steps 4 and 5: masteries sit 62 px out, sockets 58 px out, from their parent's radial direction. */
const MASTERY_DIST = 62;
const SOCKET_DIST = 58;

/** Mutable working copy of the web: nodes in creation order, indexed by id. */
class WebBuilder {
  readonly nodes: TalentNode[] = [];
  private readonly byId = new Map<string, TalentNode>();

  get(id: string): TalentNode | undefined {
    return this.byId.get(id);
  }

  add(node: TalentNode): void {
    if (this.byId.has(node.id)) {
      warn(`duplicate node ${node.id}`);
      return;
    }
    this.nodes.push(node);
    this.byId.set(node.id, node);
  }

  /** Bidirectional and idempotent; a missing endpoint warns and is skipped. */
  link(a: string, b: string): void {
    if (a === b) return;
    const A = this.byId.get(a);
    const B = this.byId.get(b);
    if (!A || !B) {
      warn(`link ${a} - ${b}: missing node`);
      return;
    }
    if (!A.links.includes(b)) A.links.push(b);
    if (!B.links.includes(a)) B.links.push(a);
  }
}

function sectorNode(row: SectorRow, x: number, y: number): TalentNode {
  const node: TalentNode = { id: row.id, name: row.name, kind: row.kind, x, y, links: [], desc: row.desc };
  if (row.classStart) node.classStart = row.classStart;
  if (row.icon) node.icon = row.icon;
  if (row.stats) node.stats = { ...row.stats };
  if (row.special) node.special = { ...row.special, params: row.special.params && { ...row.special.params } };
  return node;
}

function clusterNode(row: ClusterRow, x: number, y: number): TalentNode {
  return { id: row.id, name: row.name, kind: row.kind, x, y, links: [], desc: row.desc, fx: row.fx };
}

function masteryNode(row: MasteryRow, x: number, y: number): TalentNode {
  return {
    id: row.id,
    name: row.name,
    kind: 'mastery',
    x,
    y,
    links: [],
    choices: row.choices.map((c) => ({ name: c.name, desc: c.desc, fx: c.fx })),
  };
}

function socketNode(row: SocketRow, x: number, y: number): TalentNode {
  return { id: row.id, name: row.name, kind: 'socket', x, y, links: [], desc: row.desc };
}

/** Position of a node placed `dist` px from `parent` along the parent's radial direction plus `offDeg`. */
function radial(parent: TalentNode, offDeg: number, dist: number): Vec {
  const a = Math.atan2(parent.y, parent.x) + offDeg * DEG;
  return [round(parent.x + dist * Math.cos(a)), round(parent.y + dist * Math.sin(a))];
}

function buildSector(web: WebBuilder, s: (typeof SECTORS)[number]): void {
  const i = SECTOR_ROWS.findIndex((r) => r.id === `${s.prefix}_start`);
  const block = i < 0 ? [] : SECTOR_ROWS.slice(i, i + SECTOR_BLOCK);
  if (block.length !== SECTOR_BLOCK) {
    warn(`sector ${s.prefix}: expected ${SECTOR_BLOCK} rows, found ${block.length}`);
    return;
  }
  const [startRow, entryRow] = block;
  const startId = startRow.id;
  const [sx, sy] = s.start;
  web.add(sectorNode(startRow, sx, sy));
  web.add(sectorNode(entryRow, s.entry[0], s.entry[1]));
  web.link(startId, entryRow.id);
  for (const a of s.attach) web.link(entryRow.id, a);

  const armId = new Map<string, string>();
  const v: Vec = [-s.u[1], s.u[0]];
  let prev = startId;
  ARM_SEQUENCE.forEach((slot, j) => {
    const row = block[2 + j];
    const lat = ARM_LATERAL[slot.arm];
    const x = round(sx + s.u[0] * 68 * slot.k + v[0] * lat);
    const y = round(sy + s.u[1] * 68 * slot.k + v[1] * lat);
    web.add(sectorNode(row, x, y));
    // each arm hangs off the start node; later nodes of the arm chain to the previous one
    web.link(slot.k === 1 ? startId : prev, row.id);
    prev = row.id;
    armId.set(`${slot.arm}${slot.k}`, row.id);
  });
  // wheel cross-links at the 4th step of each arm
  web.link(armId.get('A4') ?? startId, armId.get('M4') ?? startId);
  web.link(armId.get('M4') ?? startId, armId.get('B4') ?? startId);
}

function buildCluster(web: WebBuilder, c: (typeof CLUSTERS)[number]): void {
  const byId = new Map(CLUSTER_ROWS.map((r) => [r.id, r] as const));
  const rowOf = (id: string): ClusterRow | undefined => {
    const row = byId.get(id);
    if (!row) warn(`cluster row ${id} missing`);
    return row;
  };
  const [dx, dy] = c.dir;
  const hubX = CLUSTER_HUB_DIST * dx;
  const hubY = CLUSTER_HUB_DIST * dy;
  const theta = Math.atan2(dy, dx);
  const petal: Record<'a' | 'm' | 'b', number> = {
    a: theta - PETAL_OFFSET_DEG * DEG,
    m: theta,
    b: theta + PETAL_OFFSET_DEG * DEG,
  };
  const hubId = `cl_${c.prefix}_hub`;
  const hubRow = rowOf(hubId);
  if (hubRow) web.add(clusterNode(hubRow, hubX, hubY));

  for (const arm of ['a', 'm', 'b'] as const) {
    let prev = hubId;
    for (let j = 1; j <= 3; j++) {
      const id = `cl_${c.prefix}_${arm}${j}`;
      const row = rowOf(id);
      if (!row) continue;
      const x = round(hubX + CLUSTER_STEP * j * Math.cos(petal[arm]));
      const y = round(hubY + CLUSTER_STEP * j * Math.sin(petal[arm]));
      web.add(clusterNode(row, x, y));
      web.link(prev, id);
      prev = id;
    }
  }
  web.link(`cl_${c.prefix}_a2`, `cl_${c.prefix}_m2`);
  web.link(`cl_${c.prefix}_m2`, `cl_${c.prefix}_b2`);

  const hub = web.get(hubId);
  for (let i = 0; i < 2; i++) {
    const id = `cl_${c.prefix}_c${i + 1}`;
    const row = rowOf(id);
    const inner = web.get(c.inner[i]);
    if (!row || !hub || !inner) continue;
    // connector = midpoint of the inner class node and the hub
    web.add(clusterNode(row, round((inner.x + hub.x) / 2), round((inner.y + hub.y) / 2)));
    web.link(c.inner[i], id);
    web.link(id, hubId);
  }
}

/**
 * Builds the 306-node web. `base` is RAW_BASE of data/talents.ts (the 125 original nodes); it is not mutated.
 * Creation order: base · nc connectors · sectors (pl, mk, ar, wl, nc) · clusters (kn, bb, rg) · masteries · sockets.
 */
export function buildPassiveWeb(base: readonly TalentNode[]): TalentNode[] {
  const web = new WebBuilder();
  for (const b of base) web.add({ ...b, links: [...b.links] });

  // step 1: Nekromant connectors, linked to the Büyücü web (NC_CONNECTORS)
  for (const id of Object.keys(NC_CONNECTOR_POS)) {
    const row = SECTOR_ROWS.find((r) => r.id === id);
    const pos = NC_CONNECTOR_POS[id];
    if (!row) warn(`connector row ${id} missing`);
    else web.add(sectorNode(row, pos[0], pos[1]));
  }
  for (const c of NC_CONNECTORS) web.link(c.from, c.to);

  // step 2: five sectors
  for (const s of SECTORS) buildSector(web, s);

  // step 3: three clusters
  for (const c of CLUSTERS) buildCluster(web, c);

  // step 4: masteries (dead ends next to one notable)
  for (const row of MASTERY_ROWS) {
    const parent = web.get(row.parent);
    if (!parent) {
      warn(`mastery ${row.id}: parent ${row.parent} missing`);
      continue;
    }
    const [x, y] = radial(parent, row.off, MASTERY_DIST);
    web.add(masteryNode(row, x, y));
    web.link(parent.id, row.id);
  }

  // step 5: sockets (dead ends next to one small node)
  for (const row of SOCKET_ROWS) {
    const parent = web.get(row.parent);
    if (!parent) {
      warn(`socket ${row.id}: parent ${row.parent} missing`);
      continue;
    }
    const [x, y] = radial(parent, row.off, SOCKET_DIST);
    web.add(socketNode(row, x, y));
    web.link(parent.id, row.id);
  }

  return web.nodes;
}

const EXPECTED_KINDS: Record<TalentNode['kind'], number> = {
  start: 9,
  small: 178,
  notable: 80,
  keystone: 16,
  mastery: 14,
  socket: 9,
};
const EXPECTED_TOTAL = 306;
const MIN_DISTANCE = 50;
const EXTENT = 1404;
const STAT_SET: ReadonlySet<string> = new Set<string>(STAT_IDS);

const orient = (a: TalentNode, b: TalentNode, c: TalentNode): number =>
  (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);

/**
 * The §3.3 checks: 306 nodes with the kind counts of §3.2; unique ids; links point to existing nodes and are
 * bidirectional; minimum pairwise distance 50; no crossing link segments; |x|, |y| ≤ 1404; every fx parses and every
 * `S` stat is a StatId; every node is reachable from every start. Returns the errors (empty = valid).
 * The golden comparison against docs/GDD_TALENTS.web.json is done by tools/talents-check.mjs, not here.
 */
export function validateWeb(nodes: readonly TalentNode[]): string[] {
  const errs: string[] = [];
  const byId = new Map<string, TalentNode>();
  for (const n of nodes) {
    if (byId.has(n.id)) errs.push(`duplicate id ${n.id}`);
    byId.set(n.id, n);
  }
  if (nodes.length !== EXPECTED_TOTAL) errs.push(`node count ${nodes.length} != ${EXPECTED_TOTAL}`);
  const counts: Record<string, number> = {};
  for (const n of nodes) counts[n.kind] = (counts[n.kind] ?? 0) + 1;
  for (const kind of Object.keys(EXPECTED_KINDS) as TalentNode['kind'][]) {
    const want = EXPECTED_KINDS[kind];
    if ((counts[kind] ?? 0) !== want) errs.push(`kind ${kind}: ${counts[kind] ?? 0} != ${want}`);
  }

  for (const n of nodes) {
    if (Math.abs(n.x) > EXTENT || Math.abs(n.y) > EXTENT) errs.push(`${n.id} outside ±${EXTENT}`);
    if (!Number.isFinite(n.x) || !Number.isFinite(n.y)) errs.push(`${n.id} has no finite position`);
    const seen = new Set<string>();
    for (const l of n.links) {
      if (seen.has(l)) errs.push(`${n.id} links ${l} twice`);
      seen.add(l);
      const m = byId.get(l);
      if (!m) errs.push(`${n.id} links missing node ${l}`);
      else if (!m.links.includes(n.id)) errs.push(`${l} does not link back to ${n.id}`);
    }
  }

  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const d = Math.hypot(nodes[i].x - nodes[j].x, nodes[i].y - nodes[j].y);
      if (d < MIN_DISTANCE) errs.push(`${nodes[i].id} and ${nodes[j].id} are ${d.toFixed(1)} px apart`);
    }
  }

  const edges: [TalentNode, TalentNode][] = [];
  for (const n of nodes) for (const l of n.links) {
    const m = byId.get(l);
    if (m && n.id < l) edges.push([n, m]);
  }
  for (let i = 0; i < edges.length; i++) {
    const [a, b] = edges[i];
    for (let j = i + 1; j < edges.length; j++) {
      const [c, d] = edges[j];
      if (a === c || a === d || b === c || b === d) continue;
      const d1 = orient(c, d, a);
      const d2 = orient(c, d, b);
      const d3 = orient(a, b, c);
      const d4 = orient(a, b, d);
      if (d1 * d2 < 0 && d3 * d4 < 0) errs.push(`link ${a.id}-${b.id} crosses ${c.id}-${d.id}`);
    }
  }

  const checkFx = (owner: string, fx: string): void => {
    const { items, errors } = parseFx(fx);
    for (const e of errors) errs.push(`${owner}: ${e}`);
    for (const it of items) {
      if (it.k !== 'S') continue;
      for (const key of Object.keys(it.stats)) if (!STAT_SET.has(key)) errs.push(`${owner}: unknown stat ${key}`);
    }
  };
  for (const n of nodes) {
    if (n.fx !== undefined) checkFx(n.id, n.fx);
    for (const c of n.choices ?? []) checkFx(`${n.id}/${c.name}`, c.fx);
  }

  for (const start of nodes.filter((n) => n.kind === 'start')) {
    const reached = new Set<string>([start.id]);
    const queue = [start.id];
    while (queue.length > 0) {
      const cur = byId.get(queue.pop() as string);
      for (const l of cur?.links ?? []) {
        if (!reached.has(l) && byId.has(l)) {
          reached.add(l);
          queue.push(l);
        }
      }
    }
    if (reached.size !== nodes.length) errs.push(`${start.id} reaches ${reached.size} of ${nodes.length} nodes`);
  }
  return errs;
}
